SourceCode.Declaration:
/// <summary>
/// Range values the Mobile operations workspace tile queries cannot hold as constants: times
/// counted back from now, and "not empty". Thresholds live here so they are changed in one place.
/// </summary>
public final class HSMobileOpsWorkspaceRange
{
    public static const int StuckPostingMinutes = 15;
    public static const int CycleStoppedDays    = 2;
    public static const int DeviceNotSeenDays   = 7;
}

Method.Source:
/// <summary>Posts received before this moment and still not done count as stuck.</summary>
[QueryRangeFunction]
public static str stuckBefore()
{
    return '<' + queryValue(DateTimeUtil::addMinutes(DateTimeUtil::utcNow(), -HSMobileOpsWorkspaceRange::StuckPostingMinutes));
}

/// <summary>A cycle count that last ran before this moment has stopped.</summary>
[QueryRangeFunction]
public static str cycleBefore()
{
    return '<' + queryValue(DateTimeUtil::addDays(DateTimeUtil::utcNow(), -HSMobileOpsWorkspaceRange::CycleStoppedDays));
}

/// <summary>A device last seen before this moment counts as not seen.</summary>
[QueryRangeFunction]
public static str deviceBefore()
{
    return '<' + queryValue(DateTimeUtil::addDays(DateTimeUtil::utcNow(), -HSMobileOpsWorkspaceRange::DeviceNotSeenDays));
}

/// <summary>A user is locked out while the lock runs past this moment.</summary>
[QueryRangeFunction]
public static str lockedAfter()
{
    return '>' + queryValue(DateTimeUtil::utcNow());
}

/// <summary>Matches rows where the field has a value.</summary>
[QueryRangeFunction]
public static str notEmpty()
{
    return '!' + queryValue('');
}
